package memo

import (
	"errors"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	c := New()
	calls := 0
	load := func(k string) (string, error) {
		calls++
		return "", errors.New("boom")
	}
	_, _ = c.Get("k", load)
	_, _ = c.Get("k", load)
	if calls != 1 {
		t.Fatalf("load called %d times for one key, want 1", calls)
	}
}
